<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { api, imgProxy } from '../../api/index';
import { useIdentity } from '../../stores/identity';
import GamePoster from '../../components/games/GamePoster.vue';
import GameRating from '../../components/games/GameRating.vue';
import GamePrice from '../../components/games/GamePrice.vue';
import GameContentBadge from '../../components/games/GameContentBadge.vue';
import Priority from '../../components/Priority.vue';
import GameAddModal from '../../components/games/GameAddModal.vue';
import GameEditModal from '../../components/games/GameEditModal.vue';
import HotReviews from '../../components/HotReviews.vue';
import { parseList, platformLabels, releaseLabel } from '../../utils/games';
import { fmtWatched } from '../../utils/watchedDate';

const route=useRoute(); const identity=useIdentity(); const work=ref<any>(null); const loading=ref(true); const error=ref('');
const addOpen=ref(false); const addTarget=ref('played'); const addFromPlan=ref<any>(null); const editOpen=ref(false); const editType=ref('mark'); const editRecord=ref<any>(null);
const session=computed(()=>work.value?.sessions?.[0]||null); const genres=computed(()=>parseList(work.value?.genres)); const modes=computed(()=>parseList(work.value?.play_modes)); const platforms=computed(()=>platformLabels(work.value?.platforms));
const hasPrice=computed(()=>Boolean(work.value?.is_free || work.value?.current_price != null));
const externalLabel=computed(()=>work.value?.steam_appid && work.value?.store_url?.includes('steampowered') ? '在 Steam 查看' : '查看游戏资料');
async function load(){ loading.value=true; error.value=''; try{ work.value=await api(`/api/games/works/${route.params.id}`); }catch(e){ error.value=e.body?.error||e.message; }finally{loading.value=false;} }
onMounted(load); watch([()=>route.params.id,()=>identity.viewing],load);
function add(target:string){ addFromPlan.value=null; addTarget.value=target; addOpen.value=true; }
function startPlan(){ addFromPlan.value={...work.value.plan,work:work.value}; addTarget.value='couple_playing'; addOpen.value=true; }
function edit(type:string,row:any){ editType.value=type; editRecord.value={...row,work:work.value}; editOpen.value=true; }
</script>

<template>
  <main class="page game-detail"><router-link class="back-link" to="/games"><svg viewBox="0 0 24 24"><path d="M19 12H5M11 18l-6-6 6-6"/></svg>返回游戏首页</router-link><p v-if="loading" class="game-detail__state">加载游戏资料…</p><p v-else-if="error||!work" class="game-detail__state">游戏不存在或目录服务暂时不可用。</p><template v-else><section class="game-detail-hero"><img v-if="work.header_url" class="game-detail-hero__bg" :src="imgProxy(work.header_url)" alt=""/><div class="game-detail-hero__shade"></div><GamePoster :url="work.cover_url" :fallback="work.header_url" :state="work.release_state"/><div class="game-detail-hero__body"><span class="game-detail__kicker">{{ work.igdb_id ? `IGDB ${work.igdb_id}` : `STEAM APP ${work.steam_appid}` }}</span><h1>{{ work.title }}</h1><p v-if="work.original_title" class="game-detail__original">{{ work.original_title }}</p><GameContentBadge :work="work"/><div class="game-detail__chips"><span>{{ releaseLabel(work) }}</span><span v-for="platform in platforms" :key="platform">{{ platform }}</span><span v-if="work.supports_together" class="is-accent">双人可玩</span></div><div class="game-detail__ratings"><GameRating :work="work"/><GamePrice :work="work"/></div><p class="game-detail__desc">{{ work.short_description }}</p><a v-if="work.store_url || work.source_url" class="btn btn--primary game-detail__steam" :href="work.store_url || work.source_url" target="_blank" rel="noreferrer">{{ externalLabel }}<svg class="btn__ic" viewBox="0 0 24 24"><path d="M7 17 17 7M8 7h9v9"/></svg></a></div></section>

      <section class="game-facts"><div><span>发售日期</span><strong>{{ releaseLabel(work) }}</strong></div><div><span>{{ work.review_percent!=null?'Steam 评测':'IGDB 评分' }}</span><strong>{{ work.review_percent!=null?`${work.review_percent}% · ${work.review_desc||''}`:work.catalog_rating!=null?`${Math.round(work.catalog_rating)}%`:'暂无' }}</strong></div><div><span>双人适配</span><strong>{{ work.supports_together?'支持共同游玩':'未标记双人模式' }}</strong></div><div v-if="hasPrice"><span>当前售价</span><GamePrice :work="work"/></div></section>
      <HotReviews :endpoint="`/api/games/works/${work.id}/hot-reviews`" theme="game" />
      <section class="game-detail-grid"><div class="game-detail-main"><div class="game-info-block"><h2>关于这款游戏</h2><p>{{ work.short_description || '目录中暂无简介。' }}</p></div><div class="game-info-block"><h2>类型与玩法</h2><div class="game-tag-list"><span v-for="item in genres" :key="item">{{ item }}</span><span v-for="item in modes" :key="item" class="is-mode">{{ item }}</span></div></div><div v-if="work.platform_releases?.length" class="game-info-block"><h2>平台发行</h2><div class="game-tag-list"><span v-for="(item,index) in work.platform_releases" :key="`${item.igdb_platform_id}-${index}`">{{ item.platform_abbreviation || item.platform_name }}{{ item.release_date ? ` · ${item.release_date}` : '' }}</span></div></div><div class="game-info-block game-credits"><div><span>开发商</span><strong>{{ parseList(work.developers).join('、')||'—' }}</strong></div><div><span>发行商</span><strong>{{ parseList(work.publishers).join('、')||'—' }}</strong></div></div><div class="game-info-block game-personal-records"><h2>各自的记录</h2><p v-if="!work.all_marks?.length" class="game-personal-records__empty">还没有个人评分或评价。</p><article v-for="mark in work.all_marks" :key="mark.id" class="game-personal-record" :data-who="identity.whoKey(mark.user_id)"><button v-if="mark.user_id === identity.viewing" class="card-edit" data-tip="编辑" data-tip-pos="below" aria-label="编辑自己的游戏记录" @click="edit('mark',mark)"><svg viewBox="0 0 24 24"><path d="M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z"/></svg></button><div class="game-personal-record__head"><strong>{{ identity.userById(mark.user_id)?.display_name || `用户 ${mark.user_id}` }}</strong><span v-if="mark.rating">{{ mark.rating }} 分</span></div><p v-if="mark.comment">{{ mark.comment }}</p><p v-else class="game-personal-record__empty">暂未填写评价</p></article><button v-if="!work.my_mark" class="btn btn--ghost game-personal-records__add" @click="add('played')">加入“我玩过”</button></div></div>
        <aside class="game-record-panel"><h2>共同状态</h2><div v-if="session" class="game-record-card"><span class="game-record-card__label">共同游玩</span><strong>{{ session.completed_at ? '已通关' : '正在玩' }}</strong><small v-if="session.played_at">{{ fmtWatched(session.played_at) }} 开始</small><small v-if="session.completed_at">{{ fmtWatched(session.completed_at) }} 通关</small><p v-if="session.joint_note">{{ session.joint_note }}</p><button class="btn btn--ghost" @click="edit('session',session)">编辑共同记录</button></div><div v-else-if="work.plan" class="game-record-card"><span class="game-record-card__label">共同计划</span><div class="game-record-plan"><Priority :value="work.plan.priority"/><strong>待玩</strong></div><p v-if="work.plan.note">{{ work.plan.note }}</p><div class="game-record-actions"><button class="btn btn--primary" @click="startPlan">开始一起玩</button><button class="btn btn--ghost" @click="edit('plan',work.plan)">编辑计划</button></div></div><div v-else class="game-record-card"><span class="game-record-card__label">还没有共同记录</span><p>可以现在开始，也可以先加入共同计划。</p><div class="game-record-actions"><button class="btn btn--primary" @click="add('couple_playing')">开始一起玩</button><button class="btn btn--ghost" @click="add('couple_plan')">想和你一起玩</button></div></div></aside></section>
    </template><GameAddModal v-if="work" v-model="addOpen" :initial-target="addTarget" :initial-work="work" :from-plan="addFromPlan" @added="load"/><GameEditModal v-model="editOpen" :type="editType" :record="editRecord" @changed="load"/></main>
</template>

<style scoped>
.game-detail{ padding-top:var(--s-8); }.game-detail__state{ padding:var(--s-16); text-align:center; color:var(--text-faint); }.game-detail-hero{ position:relative; display:grid; grid-template-columns:minmax(190px,270px) 1fr; gap:var(--s-8); align-items:end; min-height:500px; margin-top:var(--s-5); padding:var(--s-10); overflow:hidden; border:1px solid var(--game-line); border-radius:var(--r-xl); background:var(--surface); }.game-detail-hero__bg{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; filter:saturate(.7); opacity:.38; }.game-detail-hero__shade{ position:absolute; inset:0; background:linear-gradient(90deg,oklch(.13 .03 255 / .98) 0%,oklch(.13 .03 255 / .78) 53%,oklch(.13 .03 255 / .58)),linear-gradient(0deg,oklch(.13 .03 255 / .95),transparent 60%); }.game-detail-hero>:not(.game-detail-hero__bg,.game-detail-hero__shade){ position:relative; z-index:1; }.game-detail-hero__body{ display:flex; flex-direction:column; align-items:flex-start; gap:var(--s-3); }.game-detail__kicker{ color:var(--game-accent); font-size:10px; font-weight:800; letter-spacing:.18em; }.game-detail h1{ max-width:800px; font-size:clamp(36px,6vw,64px); line-height:1.02; }.game-detail__original{ color:var(--text-faint); }.game-detail__chips,.game-detail__ratings{ display:flex; flex-wrap:wrap; align-items:center; gap:8px; }.game-detail__chips span{ padding:3px 8px; border:1px solid var(--line); border-radius:var(--r-pill); color:var(--text-dim); font-size:11px; background:oklch(.15 .03 250 / .65); }.game-detail__chips .is-accent{ color:var(--game-accent); border-color:var(--game-line); }.game-detail__desc{ max-width:660px; color:var(--text-dim); }.game-detail__steam{ margin-top:var(--s-2); }.game-facts{ display:grid; grid-template-columns:repeat(4,1fr); gap:1px; margin:var(--s-6) 0; overflow:hidden; border:1px solid var(--line-soft); border-radius:var(--r-lg); background:var(--line-soft); }.game-facts>div{ display:flex; flex-direction:column; gap:4px; padding:var(--s-4); background:var(--surface); }.game-facts span{ color:var(--text-faint); font-size:10px; text-transform:uppercase; letter-spacing:.08em; }.game-facts strong{ font-size:13px; }.game-detail-grid{ display:grid; grid-template-columns:minmax(0,1fr) 330px; gap:var(--s-8); }.game-detail-main{ display:flex; flex-direction:column; gap:var(--s-6); }.game-info-block{ padding:var(--s-6); border:1px solid var(--line-soft); border-radius:var(--r-lg); background:var(--surface); }.game-info-block h2,.game-record-panel h2{ margin-bottom:var(--s-3); font-size:var(--fs-lg); }.game-info-block p{ color:var(--text-dim); }.game-tag-list{ display:flex; flex-wrap:wrap; gap:8px; }.game-tag-list span{ padding:5px 10px; border-radius:var(--r-pill); background:var(--surface-2); border:1px solid var(--line-soft); color:var(--text-dim); font-size:12px; }.game-tag-list .is-mode{ color:var(--game-accent); border-color:var(--game-line); background:var(--game-tint); }.game-credits{ display:grid; grid-template-columns:1fr 1fr; gap:var(--s-5); }.game-credits>div{ display:flex; flex-direction:column; }.game-credits span{ color:var(--text-faint); font-size:11px; }.game-record-panel{ display:flex; flex-direction:column; gap:var(--s-3); }.game-record-card{ display:flex; flex-direction:column; align-items:flex-start; gap:8px; padding:var(--s-4); border:1px solid var(--line-soft); border-radius:var(--r-lg); background:var(--surface); }.game-record-card__label{ color:var(--game-accent); font-size:10px; font-weight:800; letter-spacing:.1em; }.game-record-card p,.game-record-card small{ color:var(--text-faint); }.game-record-card .btn{ width:100%; justify-content:center; }.game-record-actions{ display:grid; width:100%; gap:8px; }.game-record-plan{ display:flex; align-items:center; gap:8px; }.game-personal-records{ display:flex; flex-direction:column; gap:var(--s-3); }.game-personal-records h2{ margin-bottom:0; }.game-personal-record{ position:relative; min-height:42px; padding:var(--s-3) 44px 0 0; border-top:1px solid var(--line-soft); }.game-personal-record .card-edit{ top:10px; right:0; opacity:.82; }.game-personal-record__head{ display:flex; align-items:center; justify-content:space-between; gap:var(--s-3); }.game-personal-record__head span{ color:var(--gold); font-family:var(--font-brand); font-weight:700; }.game-personal-record p{ margin-top:var(--s-2); }.game-personal-record__empty,.game-personal-records__empty{ color:var(--text-faint)!important; }.game-personal-records__add{ align-self:flex-start; }
@media(max-width:900px){ .game-detail-grid{ grid-template-columns:1fr; }.game-facts{ grid-template-columns:1fr 1fr; } }
@media(max-width:640px){ .game-detail-hero{ grid-template-columns:110px 1fr; align-items:start; min-height:390px; padding:var(--s-5); gap:var(--s-4); }.game-detail h1{ font-size:30px; }.game-detail__desc{ grid-column:1/-1; }.game-facts{ grid-template-columns:1fr; }.game-credits{ grid-template-columns:1fr; } }
</style>
